class BST:
    def __init__(self):
        self.root = None

    # Insert — O(h)
    def insert(self, val):
        self.root = self._insert(self.root, val)

    def _insert(self, node, val):
        if not node: return TreeNode(val)   # create new node
        if val < node.val:
            node.left  = self._insert(node.left,  val)
        elif val > node.val:
            node.right = self._insert(node.right, val)
        # val == node.val: duplicate — ignore
        return node

    # Search — O(h)
    def search(self, val):
        return self._search(self.root, val)

    def _search(self, node, val):
        if not node: return False
        if val == node.val: return True
        if val < node.val: return self._search(node.left,  val)
        return            self._search(node.right, val)

    # Delete — O(h)
    def delete(self, val):
        self.root = self._delete(self.root, val)

    def _delete(self, node, val):
        if not node: return None
        if val < node.val:
            node.left  = self._delete(node.left,  val)
        elif val > node.val:
            node.right = self._delete(node.right, val)
        else:   # found node to delete
            if not node.left:  return node.right  # case 1 & 2
            if not node.right: return node.left   # case 2
            # Case 3: two children — replace with inorder successor
            successor      = self._min_node(node.right)
            node.val       = successor.val
            node.right     = self._delete(node.right, successor.val)
        return node

    def _min_node(self, node):
        while node.left: node = node.left
        return node

    def inorder(self):
        result = []
        def dfs(n):
            if n:
                dfs(n.left)
                result.append(n.val)
                dfs(n.right)
        dfs(self.root)
        return result

bst = BST()
for v in [5, 3, 7, 1, 4, 6, 8]: bst.insert(v)
print(bst.inorder())    # [1, 3, 4, 5, 6, 7, 8]
print(bst.search(4))    # True
print(bst.search(9))    # False
bst.delete(3)
print(bst.inorder())    # [1, 4, 5, 6, 7, 8]
